71	fn parse_query_feature_name(p: &mut CssParser) -> ParsedSyntax {
72	    if !is_at_query_feature_name(p) {
73	        return Absent;
74	    }
75	
76	    if CssSyntaxFeatures::Scss.is_supported(p) {
77	        parse_scss_interpolated_identifier(p)
78	    } else {
79	        parse_regular_identifier(p)
